tree = (4, (2, (1, None, None), (3, None, None)), (6, None, None))

def order(t, kind):
    if t is None:
        return []
    v, l, r = t
    L, R = order(l, kind), order(r, kind)
    return {'in': L + [v] + R, 'pre': [v] + L + R, 'post': L + R + [v]}[kind]

for k in ('in', 'pre', 'post'):
    print(f'{k:<4}', order(tree, k))
